static void run_fgets_overflow(struct heap_ops *ops)
{
	char *p = ops->alloc(16);
	FILE *f;

	zassert_not_null(p, "alloc failed");

	/*
	 * Use fmemopen to avoid dependency on stdin. The ASAN check for fgets
	 * happens before any data is read, so the stream can be empty.
	 */
	f = fmemopen(NULL, 0, "r");
	if (f == NULL) {
		ops->free(p);
		ztest_test_skip();
		return;
	}

	ASSERT_VIOLATION(do_fgets(p, 17, f));

	fclose(f);
	ops->free(p);
}
